SINA_SMART["fa-endocrine"] = {"lecture":"fa-endocrine","title":"Endocrine function: endocrine crises","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"fa-endocrine:s0","text":"Describe and explain: The big picture","topic":"The big picture","sec":0,"importance":"standard","highYield":"insufficient-source"},{"id":"fa-endocrine:e0","text":"Adrenal cortex: glomerulosa (aldosterone), fasciculata (cortisol), reticularis (androgens).","topic":"Adrenal function and adrenal crisis","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"fa-endocrine:e1","text":"Addison disease appears at about 90% loss of adrenal function.","topic":"Adrenal function and adrenal crisis","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"fa-endocrine:e2","text":"Adrenal crisis: refractory hypotension, may mimic septic shock.","topic":"Adrenal function and adrenal crisis","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"fa-endocrine:e3","text":"Adrenal crisis labs: low Na, high K, low glucose.","topic":"Adrenal function and adrenal crisis","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"fa-endocrine:e4","text":"Suspect it if prednisone > 7.5 mg/day for > 3 weeks.","topic":"Adrenal function and adrenal crisis","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"fa-endocrine:e5","text":"Treat with saline and hydrocortisone after sending cortisol and ACTH.","topic":"Adrenal function and adrenal crisis","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"fa-endocrine:e6","text":"Alpha → glucagon, beta → insulin, delta → somatostatin.","topic":"Endocrine pancreas and DKA","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"fa-endocrine:e7","text":"DKA: hyperglycaemia + ketones + acidosis; Kussmaul breathing, fruity breath.","topic":"Endocrine pancreas and DKA","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"fa-endocrine:e8","text":"DKA: serum K high but total body K depleted; avoid hypokalaemia.","topic":"Endocrine pancreas and DKA","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"fa-endocrine:e10","text":"Storm treatment: beta-blocker, PTU/methimazole, dexamethasone, iodine, cooling.","topic":"Thyroid hormone and thyroid storm","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"fa-endocrine:e9","text":"Thyroid storm: HR > 140, fever > 41 °C, CNS dysfunction.","topic":"Thyroid hormone and thyroid storm","sec":3,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"vj8u6i":"a","1cvg9k2":"a","x7ptgg":"a","1p7fejn":"a","f4jqqo":"a","fz8206":"a","ak54rw":"a","1udfjsv":"a","1ey4mrp":"a","1n91mbl":"a","1jtdiag":"a","d7mcb9":"a","8sh428":"a","1wwg5jw":"a","1f1lcrh":"a","1l2brr2":"a","a632jm":"a","lyuunw":"a","bg5k49":"a","1kbhjy6":"a","fdb40l":"a","sc4bbc":"a","inp5gu":"a","xp39fw":"a","1vta9c4":"a","1qqwx2o":"a","1h1umzl":"a","xbnue5":"x","or5g35":"x"},"mapCounts":{"verified":0,"auto":27,"ambiguous":0,"missing":2},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"fa-endocrine:s0":{"s":0,"u":["The endocrine system coordinates cell and organ function to maintain homeostasis: sodium, water and blood pressure; calcium and phosphate; energy balance and fuel use; the stress response; reproduction, growth and senescence.","The hypothalamus leads it through the pituitary."],"dp":[]},"fa-endocrine:e0":{"s":1,"u":["Adrenal cortex: glomerulosa (aldosterone), fasciculata (cortisol), reticularis (androgens).","The adrenal cortex has three layers: zona glomerulosa (aldosterone), fasciculata (cortisol), reticularis (androgens: DHEA, androstenedione); the medulla makes catecholamines for the stress response."],"dp":[]},"fa-endocrine:e1":{"s":1,"u":["Addison disease appears at about 90% loss of adrenal function.","Insufficiency is primary (gland destruction; Addison disease appears when about 90% of function is lost, so both cortisol and aldosterone fail) or secondary (low ACTH, commonly after prolonged glucocorticoid therapy)."],"dp":[]},"fa-endocrine:e2":{"s":1,"u":["Adrenal crisis: refractory hypotension, may mimic septic shock.","Presentation : nonspecific weakness, weight loss, abdominal pain, fever; classically refractory hypotension , often mimicking septic shock, sometimes without reflex tachycardia; think of it in anyone on more than 7.5 mg prednisone for over 3 weeks."],"dp":[{"h":"Why adrenal crisis resists vasopressors","t":"Cortisol is permissive for catecholamines: it keeps vascular receptors responsive and supports their synthesis. Without cortisol, vessels respond poorly to noradrenaline and the heart may not even speed up. That is why the lecture says to think of adrenal crisis when hypotension persists despite fluids and several vasopressors. Source: the lecture's adrenal crisis critical presentation slide."}]},"fa-endocrine:e3":{"s":1,"u":["Adrenal crisis labs: low Na, high K, low glucose.","Labs : hyponatraemia, hyperkalaemia, hypoglycaemia.","Insufficiency is primary (gland destruction; Addison disease appears when about 90% of function is lost, so both cortisol and aldosterone fail) or secondary (low ACTH, commonly after prolonged glucocorticoid therapy)."],"dp":[]},"fa-endocrine:e4":{"s":1,"u":["Suspect it if prednisone > 7.5 mg/day for > 3 weeks.","Presentation : nonspecific weakness, weight loss, abdominal pain, fever; classically refractory hypotension , often mimicking septic shock, sometimes without reflex tachycardia; think of it in anyone on more than 7.5 mg prednisone for over 3 weeks."],"dp":[]},"fa-endocrine:e5":{"s":1,"u":["Treat with saline and hydrocortisone after sending cortisol and ACTH.","Management : ABCs, saline bolus, rule out sepsis, antibiotics if needed, vasopressors, send cortisol and ACTH, then hydrocortisone ."],"dp":[]},"fa-endocrine:e6":{"s":2,"u":["Alpha → glucagon, beta → insulin, delta → somatostatin.","Islets: alpha cells → glucagon (raises glucose), beta cells → insulin (lowers glucose), delta cells → somatostatin (inhibits both).","Glucagon does the reverse and increases beta-oxidation."],"dp":[]},"fa-endocrine:e7":{"s":2,"u":["DKA: hyperglycaemia + ketones + acidosis; Kussmaul breathing, fruity breath.","Signs: polyuria, polydipsia, polyphagia, abdominal pain, vomiting, confusion, Kussmaul breathing with a fruity odour ; critical cases: profound hypotension, coma.","DKA : without insulin, cells starve despite hyperglycaemia; fatty acids make ketones → ketoacidosis ; glucose in the urine causes osmotic diuresis and dehydration; acidosis shifts K+ out of cells (serum hyperkalaemia) while total body potassium is depleted."],"dp":[]},"fa-endocrine:e8":{"s":2,"u":["DKA: serum K high but total body K depleted; avoid hypokalaemia.","DKA : without insulin, cells starve despite hyperglycaemia; fatty acids make ketones → ketoacidosis ; glucose in the urine causes osmotic diuresis and dehydration; acidosis shifts K+ out of cells (serum hyperkalaemia) while total body potassium is depleted.","Treatment : IV insulin, water and salt, correct electrolytes, avoid hypokalaemia , close monitoring, prevent cerebral oedema."],"dp":[{"h":"Why insulin can make DKA potassium fall dangerously","t":"In DKA potassium is pushed out of cells by acidosis and lost in the urine, so the blood level looks high while the body is depleted. Insulin drives potassium back into cells within hours, unmasking the deficit and risking arrhythmias. Hence 'avoid hypokalaemia' in the treatment list. Source: the lecture's DKA pathophysiology and treatment slides."}]},"fa-endocrine:e10":{"s":3,"u":["Storm treatment: beta-blocker, PTU/methimazole, dexamethasone, iodine, cooling.","Management : ABCs, fluids, control agitation, aggressive cooling, treat the precipitant, beta-blockade , block synthesis ( propylthiouracil, methimazole ), block T4 → T3 ( dexamethasone ), block release ( iodine )."],"dp":[]},"fa-endocrine:e9":{"s":3,"u":["Thyroid storm: HR > 140, fever > 41 °C, CNS dysfunction.","Presentation : tachycardia often over 140/min , fever sometimes over 41 °C , sweating, GI symptoms, agitation or delirium; critical: high-output heart failure, AF with rapid response, coma, seizures."],"dp":[]}},"meta":{"vj8u6i":{"a":"recall","vg":"fa-endocrine:s0/recall/1"},"1cvg9k2":{"a":"recall","vg":"fa-endocrine:e0/recall/1"},"x7ptgg":{"a":"recall","vg":"fa-endocrine:e1/recall/1"},"1p7fejn":{"a":"relationship","vg":"fa-endocrine:e1/relationship/1"},"f4jqqo":{"a":"recall","vg":"fa-endocrine:e2/recall/1"},"fz8206":{"a":"recall","vg":"fa-endocrine:e4/recall/1"},"ak54rw":{"a":"recall","vg":"fa-endocrine:e3/recall/1"},"1udfjsv":{"a":"recall","vg":"fa-endocrine:e5/recall/1"},"1ey4mrp":{"a":"recall","vg":"fa-endocrine:e6/recall/1"},"1n91mbl":{"a":"recall","vg":"fa-endocrine:e6/recall/2"},"1jtdiag":{"a":"recall","vg":"fa-endocrine:e7/recall/1"},"d7mcb9":{"a":"recall","vg":"fa-endocrine:e8/recall/1"},"8sh428":{"a":"recall","vg":"fa-endocrine:e8/recall/2"},"1wwg5jw":{"a":"recall","vg":"fa-endocrine:e9/recall/1"},"1f1lcrh":{"a":"recall","vg":"fa-endocrine:e10/recall/1"},"1l2brr2":{"a":"recall","vg":"fa-endocrine:e10/recall/2"},"a632jm":{"a":"recall","vg":"fa-endocrine:e0/recall/1"},"lyuunw":{"a":"recall","vg":"fa-endocrine:e1/recall/2"},"bg5k49":{"a":"recall","vg":"fa-endocrine:e2/recall/1"},"1kbhjy6":{"a":"recall","vg":"fa-endocrine:e3/recall/1"},"fdb40l":{"a":"recall","vg":"fa-endocrine:e6/recall/1"},"sc4bbc":{"a":"relationship","vg":"fa-endocrine:e8/relationship/1"},"inp5gu":{"a":"recall","vg":"fa-endocrine:e8/recall/1"},"xp39fw":{"a":"recall","vg":"fa-endocrine:e7/recall/1"},"1vta9c4":{"a":"recall","vg":"fa-endocrine:e9/recall/1"},"1qqwx2o":{"a":"recall","vg":"fa-endocrine:e10/recall/1"},"1h1umzl":{"a":"recall","vg":"fa-endocrine:e10/recall/2"}},"explRev":"59351ea4d8f8"};
